entry.string:
import u: ^.utils;

struct single_sig_args {
    flags: set<text>;
    pubkey;
}

struct multi_sig_args {
    flags: set<text>;
    signatures_required: integer;
    pubkeys: list<pubkey>;
}

/*
 * Returns VALID if valid.
 */
function check_single_sig_auth(args: byte_array, participants: list<byte_array>, required_flags: list<text>): u.validation_result {
    if(participants.size() > 1) {
        return u.invalid("Single sig Auth Descriptor must have only one participant.");
    }
    if (participants.size() < 1) {
        return u.invalid("Single sig Auth Descriptor's participant list is empty.");
    }

    val ss_args = single_sig_args.from_bytes(args);
    if ( check_required_flags(ss_args.flags, required_flags)) {
        if (op_context.is_signer(participants[0])) {
            return u.VALID;
        } else {
            return u.invalid("The participant is not the signer of this transaction.");
        }
    } else {
        return u.invalid("Some required flags " + required_flags.to_text() + " are missing on the (single sig) Auth Descriptor.");
    }
}

/*
 * Returns VALID if valid.
 */
function check_multi_sig_auth(args: byte_array, participants: list<byte_array>, required_flags: list<text>): u.validation_result {
    val multi_sign_args = multi_sig_args.from_bytes(args);
    if (not (check_required_flags(multi_sign_args.flags, required_flags))) {
       return u.invalid("Some required flags " + required_flags.to_text() + " are missing on the (multi sig) Auth Descriptor.");
    }
    var num_sign = multi_sign_args.signatures_required;
    for(s in participants) {
        if(op_context.is_signer(s)) {
            num_sign -= 1;
            if(num_sign < 1) {
                return u.VALID;
            }
        }
    }
    return u.invalid("Transaction must be signed by at least " + multi_sign_args.signatures_required + " participants in the Auth Descriptor.");
}

/*
 * Returns false if any of the required flags are missing from the "flags" set.
 */
function check_required_flags(flags: set<text>, required_flags: list<text>): boolean {
    return flags.contains_all(required_flags);
}

/*
 * Returns the set of flags found in the "args" parameter.
 */
function get_flags_from_args(a_t: auth_type, args: byte_array): set<text> {
    when (a_t) {
        S -> {
            return single_sig_args.from_bytes(args).flags;
        }
        M -> {
            return multi_sig_args.from_bytes(args).flags;
        }
        else -> {
            val f = set<text>();
            return f;
        }
    }
}

/*
 * Returns VALID if authentication arguments are valid.
 */
function check_auth_args(a_t: auth_type, args: byte_array, participants: list<byte_array>, required_flags: list<text>): u.validation_result {
    return when (a_t) {
        S -> check_single_sig_auth(args, participants, required_flags);
        M -> check_multi_sig_auth(args, participants, required_flags);
        else -> u.invalid("Don't recognize authentication type (S or M).");
    };
}

/*
 * Will:
 * 1. Explode if any expiry rule is broken.
 * 2. Explode if required flags are missing on the Auth Desc.
 * 3. Update the expiry rule values.
 * 4. Clean away expired Auth Descs on the account.
 */
function require_auth(account, account_auth_descriptor, required_flags: list<text>) {
	require(is_valid(account_auth_descriptor), "Invalid Auth Descriptor structure.");

	val result: u.validation_result = check_auth_args(
       		account_auth_descriptor.auth_type,
       		account_auth_descriptor.args,
            get_participants(account_auth_descriptor.auth_type, account_auth_descriptor.args),
       		//auth_descriptor_participant @* { account_auth_descriptor } ( .id ),
       		required_flags
	);

    require(result.valid, result.error!!); // Prints a precise error message.

    update_auth_descriptor_rule_variables(account_auth_descriptor);
    delete_expired_auth_descriptors(account);
}

function get_participants(a_t: auth_type, args: byte_array): list<byte_array>{
    var participants: list<byte_array>? = null;
    if (a_t == auth_type.S or a_t == auth_type.ES){
        participants = [single_sig_args.from_bytes(args).pubkey];
    }
    if (a_t == auth_type.M or a_t == auth_type.EM) {
        participants = multi_sig_args.from_bytes(args).pubkeys;
    }
    //TODO: add extendable callback for custom types
    return require(participants, "Unknown auth_descriptor type"); // or return empty list?
}

enum rule_variable {
	block_height,
	block_time,
	op_count
}

enum rule_operator {
	lt,
	le,
	eq,
	ge,
	gt
}

struct rule_expression {
	variable: text;
	operator: text;
	value: gtv;
}

entity auth_descriptor_rule_variable {
	key account_auth_descriptor, name;
	mutable value: byte_array;
}

function is_valid(auth_descriptor: account_auth_descriptor): boolean {
	if (auth_descriptor.rules == null.to_gtv().to_bytes()) {
		return true;
	}

	return is_rule_valid(
		gtv.from_bytes(auth_descriptor.rules), 
		load_variables(auth_descriptor)
	);
}

function is_rule_valid(rule: gtv, variables: map<text, gtv>): boolean {
	val parameters = list<gtv>.from_gtv(rule);
	val operator = text.from_gtv(parameters[1]);

	if (operator == "and") {
		return handle_composed_rule(rule, variables);
	} else {
		return handle_single_rule(rule, variables);
	}
}

function handle_single_rule(rule: gtv, variables: map<text, gtv>): boolean {
	return evaluate_int_variable_rule(
		rule_expression.from_gtv(rule), 
		variables
	);	
}


function handle_composed_rule(rule: gtv, variables: map<text, gtv>): boolean {
	val parameters = list<gtv>.from_gtv(rule);
	val operator = text.from_gtv(parameters[1]);
	if (operator == "and") {
		return is_rule_valid(parameters[0], variables) and is_rule_valid(parameters[2], variables);
	} else {
		return false;
	}
}

function is_active(account_auth_descriptor): boolean {
	if (account_auth_descriptor.rules == null.to_gtv().to_bytes()) { 
		return true;
	}

	return is_rule_active(gtv.from_bytes(account_auth_descriptor.rules), map<text, gtv>());
}


function is_rule_active(r: gtv, variables: map<text, gtv>): boolean {
	val parameters = list<gtv>.from_gtv(r);
	val operator = text.from_gtv(parameters[1]);
	when (operator) {
		"and" -> {
			return is_rule_active(parameters[0], variables) and is_rule_active(parameters[2], variables);
		}
		else -> {
			return is_simple_rule_active(r, variables);
		}
	}
}

function is_simple_rule_active(rule: gtv, variables: map<text, gtv>): boolean {
	val parameters = list<gtv>.from_gtv(rule);
	val variable_name = text.from_gtv(parameters[0]);
	when (rule_variable.value(variable_name)) {
		rule_variable.block_height -> {
			return is_block_height_rule_active(rule);
		}
		rule_variable.block_time -> {
			return is_block_time_rule_active(rule);
		}		
		rule_variable.op_count -> {
			return is_op_count_rule_active(rule);
		}
	}
}

/*
 *  Variables
 */

function evaluate_int_variable_rule(rule: rule_expression, variables: map<text, gtv>): boolean {
	val variable = rule_variable.value(rule.variable);
	val operator = rule_operator.value(rule.operator);
	val current_value = variable_value(variable, variables);
	val defined_value = integer.from_gtv(rule.value);

	when (operator) {
		rule_operator.lt -> {
			return current_value < defined_value;
		}
		rule_operator.le -> {
			return current_value <= defined_value;
		}
		rule_operator.eq -> {
			return current_value == defined_value;
		}
		rule_operator.ge -> {
			return current_value >= defined_value;
		}
		rule_operator.gt -> {
			return current_value > defined_value;
		}
	}
}


/*
 * Called from _add_auth_descriptor function
 */
function setup_auth_descriptor_variables(account_auth_descriptor) {

	if (account_auth_descriptor.rules == null.to_gtv().to_bytes()) {
		return;
	} 

	val variables = get_variable_names_set(gtv.from_bytes(account_auth_descriptor.rules));

	for (variable in variables) {
		when (variable) {
			rule_variable.op_count.name -> {
				create auth_descriptor_rule_variable(
					account_auth_descriptor,
					name = variable,
					value = op_count_variable_initial_value().to_bytes()
				);
			}
		}
	}
}

function update_variables(account_auth_descriptor, variables: map<text, gtv>) {
	for ((name, value) in variables) {
		val variable = require(
			auth_descriptor_rule_variable @? { account_auth_descriptor, name },
			"No auth descriptor variable found: %s, %s".format(name, integer.from_gtv(value))
			);
		val int_value = integer.from_gtv(value);

		when (name) {
			rule_variable.op_count.name -> {
				variable.value = (int_value + 1).to_gtv().to_bytes();
			}
		}
	}
}

function variable_value(variable: rule_variable, variables: map<text, gtv>): integer {
	when (variable) {
		rule_variable.block_height -> {
			return op_context.block_height;
		}
		rule_variable.block_time -> {
			return op_context.last_block_time;
		}
		rule_variable.op_count -> {
			return integer.from_gtv(variables[rule_variable.op_count.name]);
		}
	}
}

/*
 * Analyze the rules before assigning them to an authenticator descriptor
 */
 function analyze_auth_descriptor_rules(rules: gtv, hop: integer) {
 	require(hop<3, "Too many rules");
 	if (rules == null.to_gtv()) {
		return;
	}

 	val params = list<gtv>.from_gtv(rules);
 	require(params.size() <=3, "Too many params");

 	val operator = text.from_gtv(params[1]);
 	if(operator == "and") {
 		analyze_auth_descriptor_rules(params[0], hop+1); 
 		analyze_auth_descriptor_rules(params[2], hop+1);
 	} 	

	return;
 }

/*
 * Returns set of variable names used in a rule
 */
function get_variable_names_set(rules: gtv): set<text> {
	val parameters = list<gtv>.from_gtv(rules);
	val operator = text.from_gtv(parameters[1]);
	var vars = set<text>();
	if (operator == "and") {
		vars.add_all(get_variable_names_set(parameters[0]));
		vars.add_all(get_variable_names_set(parameters[2]));
	} else {
		vars.add(text.from_gtv(parameters[0]));
	}
	return vars;
} 

function load_variables(account_auth_descriptor): map<text, gtv> {
	val variables = auth_descriptor_rule_variable @* { account_auth_descriptor };

	val variables_map = map<text, gtv>();
	for (variable in variables) {
		variables_map[variable.name] = gtv.from_bytes(variable.value);
	}

	return variables_map;
}

function update_auth_descriptor_rule_variables(account_auth_descriptor) {
	val variables = load_variables(account_auth_descriptor);
	update_variables(account_auth_descriptor, variables);
}

/*
 * auth descriptor cleanup
 */

function delete_expired_auth_descriptors(account) {
	val auth_descriptors = account_auth_descriptor @* { account };

	for (auth_descriptor in auth_descriptors) {
		if (is_active(auth_descriptor) and not is_valid(auth_descriptor)) {
			_delete_auth_descriptor(auth_descriptor);
		}
	}
}

/****************************************************************************************
 *                                     block_time                                       *
 ****************************************************************************************/

function is_block_time_rule_active(r: gtv): boolean {
	val parameters = list<gtv>.from_gtv(r);
	val operator = rule_operator.value(text.from_gtv(parameters[1]));
	val value = integer.from_gtv(parameters[2]);
	when (operator) {
		rule_operator.gt -> {
			return op_context.last_block_time > value;
		}
		rule_operator.ge,
		rule_operator.eq -> {
			return op_context.last_block_time >= value;
		}
		else -> {
			return true;
		}
	}
}


/****************************************************************************************
 *                                  block_height                                        *
 ****************************************************************************************/

function is_block_height_rule_active(r: gtv): boolean {
	val parameters = list<gtv>.from_gtv(r);
	val operator = rule_operator.value(text.from_gtv(parameters[1]));
	val value = integer.from_gtv(parameters[2]);
	when (operator) {
		rule_operator.gt -> {
			return op_context.block_height > value;
		}
		rule_operator.ge,
		rule_operator.eq -> {
			return op_context.block_height >= value;
		}
		else -> {
			return true;
		}
	}
}


/****************************************************************************************
 *                                     op_count                                         *
 ****************************************************************************************/

 function op_count_variable_initial_value(): gtv {
 	return (1).to_gtv();
 }

 function is_op_count_rule_active(rule: gtv): boolean {
 	return true;
 }

struct eth_auth_args {
    account;
    account_auth_descriptor;
    signatures: list<auth.signature>;
}

function AuthDescriptor(id: byte_array) = require(
    account_auth_descriptor @? { id },
    "Provided auth descriptor id does not exist %s".format(id)
);

function Account(id: byte_array) = require(
    account @? { id },
    "Account not found: %s".format(id)
);

// TODO: Merge with `authenticate` function.
function _authenticate(required_flags: set<text>, message_template: text? = null): account {
    require(op_context.op_index > 0, "Expected at least two operations");

    val previous_op = op_context.get_all_operations()[op_context.op_index - 1];
    require(
        previous_op.name in ["ft4.evm_auth", "ft4.ft_auth"],
        "Error authenticating operation. Incorrect auth operation %s".format(previous_op.name)
    );

    val account = when (previous_op.name) {
        "ft4.evm_auth" -> _validate_eth_signature(previous_op, required_flags, message_template);
        "ft4.ft_auth" -> _validate_ft4_signature(previous_op.args, required_flags);
        else -> null;
    };

    val valid_account = require(account, "Invalid auth operation: %s".format(previous_op.name));

    rate_limit(valid_account);

    return valid_account;
}

function _validate_eth_signature(auth_op: gtx_operation, required_flags: set<text>, auth_message_template: text?): account {
    val validated_args = _validate_eth_arguments(auth_op.args, required_flags);
    val op_to_auth = op_context.get_all_operations()[op_context.op_index];
    val template = auth_message_template ?: auth.generate_auth_message_template(chain_context.blockchain_rid, op_to_auth);
    val message = create_message_from_template(
        validated_args, 
        template, 
        op_to_auth.args, 
        validated_args.account_auth_descriptor.ctr
    );

    var recovered_keys = 
        if (validated_args.account_auth_descriptor.auth_type in [auth_type.ES, auth_type.S]) [_recover_eth_key(message, validated_args.signatures[0], validated_args.account_auth_descriptor.id)] 
        else _recover_multiple_eth_keys(message, validated_args.signatures, validated_args.account_auth_descriptor);

    validated_args.account_auth_descriptor.ctr += 1;

    return validated_args.account;
}

function create_message_from_template(eth_auth_args, message_template: text, args: list<gtv>, ctr: integer): text {
    require(message_template.contains("{nonce}"), "Message template has to include '{nonce}'");
    var message = message_template;

    // TODO: check if this is still needed
    for (i in range(args.size())) {
        message = message.replace("{%d}".format(i), "%s".format(args[i]).replace("\"", ""));
    }

    return message
        .replace("{account_id}", eth_auth_args.account.id.to_hex())
        .replace("{auth_descriptor_id}", eth_auth_args.account_auth_descriptor.id.to_hex())
        .replace("{nonce}", ctr.to_text().replace("\"", ""));
}

function _validate_eth_arguments(auth_args: list<gtv>, required_flags: set<text>): eth_auth_args {
    require(auth_args.size() == 3, "Incorrect number of arguments to auth operation");

    val account_id = byte_array.from_gtv(auth_args[0]);
    val auth_descriptor_id = byte_array.from_gtv(auth_args[1]);
    val signatures = list<auth.signature>.from_gtv(auth_args[2]);

    val account = Account(account_id);

    val auth_descriptor = require(
        account_auth_descriptor @? { .id == auth_descriptor_id, .account == account },
        "Auth descriptor '%s' not found for account '%s'".format(auth_descriptor_id, account_id)
    );

    require(is_valid(auth_descriptor));

    val has_all_flags = when (auth_descriptor.auth_type) {
        S, ES -> single_sig_args.from_bytes(auth_descriptor.args).flags.contains_all(required_flags);
        M, EM -> multi_sig_args.from_bytes(auth_descriptor.args).flags.contains_all(required_flags);
    };

    require(has_all_flags, "The auth descriptor does not have the required permissions");

    return eth_auth_args(account, auth_descriptor, signatures);
}

function _recover_multiple_eth_keys(message: text, signatures: list<auth.signature>, account_auth_descriptor) {
    var recovered_keys = list<byte_array>();
    for (i in range(signatures.size())) {
        recovered_keys.add(
            _recover_eth_key(
                message,
                signatures[i],
                account_auth_descriptor.id
            )
        );
    }
    require(
        recovered_keys.size() >= multi_sig_args.from_bytes(account_auth_descriptor.args).signatures_required, 
        "Minimum number of valid signatures not reached"
    );
    return recovered_keys;
}

function _recover_eth_key(message: text, auth.signature, auth_descriptor_id: byte_array) {
    require(message != "", "Empty messages are not allowed");

    val msg_hash = keccak256(("\u0019Ethereum Signed Message:\n" + message.size().to_text() + message).to_bytes());
    val eth_pubkey = eth_ecrecover(
        signature.r,
        signature.s,
        signature.v - 27,
        msg_hash
    );

    val recovered_address = keccak256(eth_pubkey).sub(12);
    val participant = auth_descriptor_participant @? {
        .account_auth_descriptor.id == auth_descriptor_id,
        .id == recovered_address
    };
    require(participant, "Invalid signature");

    return recovered_address;
}

function _validate_ft4_signature(auth_args: list<gtv>, required_flags: set<text>): account {
    val account_id = byte_array.from_gtv(auth_args[0]);
    val auth_descriptor_id = byte_array.from_gtv(auth_args[1]);

    val account = Account(account_id);
    val external = auth_descriptor_participant @? {
        .account_auth_descriptor.account == account,
        .account_auth_descriptor.id == auth_descriptor_id, 
        .id in op_context.get_signers()
    };
    require(external, "The provided key(s) is not a signer of this auth descriptor");

    require_auth(
        external.account_auth_descriptor.account,
        external.account_auth_descriptor,
        list(required_flags)
    );

    return account;
}

import acc: ^^.accounts;
import ^^.assets;
import ^^.auth;

query delete_auth_descriptor_auth_data(gtv) = auth.auth_data(
    ["A"], 
    "Do you want to delete auth descriptor from account %s? Nonce: %s"
);

operation delete_auth_descriptor(account_id: byte_array, auth_descriptor_id: byte_array, delete_descriptor_id: byte_array) {
    val flags = if (auth_descriptor_id == delete_descriptor_id) list<text>() else ["A"];

    val account = acc.account_by_id(account_id);
    acc._auth(account, 
        acc.auth_descriptor_by_id(account, auth_descriptor_id),
        flags
    );

    acc._delete_auth_descriptor(
        acc.auth_descriptor_by_id(account, delete_descriptor_id)
    );
}

function delete_auth_descriptor_message(gtv) {
    val params = struct<delete_auth_descriptor_v2>.from_gtv(gtv);
    return "Please sign the message\nto delete auth descriptor:\n%s\n\nfrom account\n{account_id}\n\nNonce: {nonce}".format(params.auth_descriptor_id);
}

@extend(auth.auth_handler)
function () = auth.add_auth_handler(
    scope = "ft4.delete_auth_descriptor_v2",
    flags = ["A"],
    message = delete_auth_descriptor_message(*)
);

operation delete_auth_descriptor_v2(auth_descriptor_id: byte_array) {
    // val flags = if (auth_descriptor_id == delete_descriptor_id) list<text>() else ["A"];
    val account = auth.authenticate();

    acc._delete_auth_descriptor(
        acc.auth_descriptor_by_id(account, auth_descriptor_id)
    );    
}

query delete_all_auth_descriptors_exclude_auth_data(gtv) = auth.auth_data(
    ["A"], 
    "Do you want to delete all auth descriptors from account %s? Nonce: %s"
);

operation delete_all_auth_descriptors_exclude(account_id: byte_array, auth_descriptor_id: byte_array) {
    val account =  acc.account_by_id(account_id);
    val auth_descriptor = acc.auth_descriptor_by_id(account, auth_descriptor_id);
    acc._auth(account, auth_descriptor, ["A"]);

    acc._delete_all_auth_descriptors_exclude(auth_descriptor);
}

query add_auth_descriptor_auth_data(gtv) = auth.auth_data(
    ["A"], 
    "Do you want to add auth descriptor to account %s? Nonce: %s"
);

operation add_auth_descriptor(account_id: byte_array, auth_id: byte_array, new_desc: acc.auth_descriptor) {
    val account = acc.account_by_id(account_id);
    acc._auth(account, acc.auth_descriptor_by_id(account, auth_id), ["A"]);
    acc.add_auth_descriptor_to_account(account, new_desc);
}

function add_auth_descriptor_message(gtv) {
    val params = struct<add_auth_descriptor_v2>.from_gtv(gtv);
    val flags = params.new_desc.args[0];

    return "Please sign the message\nto add auth descriptor\nwith flags:\n%s\n\nto account:\n{account_id}\n\nNonce: {nonce}".format(flags);
}

@extend(auth.auth_handler)
function () = auth.add_auth_handler(
    scope = "ft4.add_auth_descriptor_v2",
    flags = ["A"],
    message = add_auth_descriptor_message(*)
);

operation add_auth_descriptor_v2(new_desc: acc.auth_descriptor) {
    val account = auth.authenticate();
    acc.add_auth_descriptor_to_account(account, new_desc);
}

import acc: ^;
import utils: ^^.utils;

query get_config() {
    return (
        rate_limit_active = acc.config.rate_limit_active,
        rate_limit_max_points = acc.config.rate_limit_max_points,
        rate_limit_recovery_time = acc.config.rate_limit_recovery_time,
        rate_limit_points_at_account_creation = acc.config.rate_limit_points_at_account_creation
    );
}

query get_account_rate_limit_last_update(account_id: byte_array) {
    if (acc.config.rate_limit_active == false) return (points = 0, last_update = 0);

    return acc.rl_state @ { .account.id == account_id }
    (
        .points, 
        .last_update
    );
}

query is_auth_descriptor_valid(account_id: byte_array, auth_descriptor_id: byte_array) {
    return acc.is_valid(acc.account_auth_descriptor @ {
        .account.id == account_id,
        .id == auth_descriptor_id
    });
}

query get_account_auth_descriptors(id: byte_array) {
    return acc.account_auth_descriptor @* {
        .account.id == id
    } (
        auth_type = .auth_type,
        args = gtv.from_bytes(.args),
        rules = gtv.from_bytes(.rules)
    );
}

query get_account_auth_descriptors_paginated(id: byte_array, page_size: integer, page_cursor: text?) {
    val descriptors = acc.get_paginated_auth_descriptors(id, page_size, page_cursor);
    val pagination_results = descriptors @* {} ( utils.pagination_result(data = (
        auth_type = .auth_type,
        args = .args,
        rules = .rules
    ).to_gtv_pretty(), rowid = .rowid) );
    return utils.make_page(pagination_results, page_size);
}

query get_account_auth_descriptors_by_participant_id(account_id: byte_array, participant_id: byte_array) {
    return (ad: acc.account_auth_descriptor, p: acc.auth_descriptor_participant) @* {
        ad.account.id == account_id,
        p.id == participant_id,
        ad == p.account_auth_descriptor
    } (
        auth_type = ad.auth_type,
        args = gtv.from_bytes(ad.args),
        rules = gtv.from_bytes(ad.rules)
    );
}

query get_account_by_id(id: byte_array) {
    return acc.account @? { id } ( .id );
}

query get_account_by_auth_descriptor(acc.auth_descriptor) {
    return acc.account @? { .id == auth_descriptor.hash() } ( .id );
}

query get_accounts_by_participant_id(id: byte_array) {
    return acc.auth_descriptor_participant @* { id } ( .account_auth_descriptor.account.id );
}

query get_accounts_by_auth_descriptor_id(id: byte_array) {
    return acc.account_auth_descriptor @* { id } ( .account.id );
}

query get_accounts_by_auth_descriptor_id_paginated(id: byte_array, page_size: integer, page_cursor: text?) {
    return utils.make_page(
        acc.get_paginated_accounts_by_ad_id(id, page_size, page_cursor),
        page_size);
}

query get_auth_descriptor_nonce(
    account_id: byte_array, 
    auth_descriptor_id: byte_array
) = acc.account_auth_descriptor @ { 
        .account.id == account_id, 
        .id == auth_descriptor_id 
    } ( .ctr );

@mount('ft')
module;

struct module_args {
	rate_limit_active: boolean;
	rate_limit_max_points: integer;
    rate_limit_recovery_time: integer;
    rate_limit_points_at_account_creation: integer;    
}

import ^.auth;
import ^.utils;

enum auth_type {
    S, M, ES, EM,
}

struct auth_descriptor {
    auth_type;
    args: list<gtv>;
    rules: gtv;
}

entity account {
    key id: byte_array;
}

entity account_meta {
    meta_key: text;
    value: byte_array;
    index account, meta_key;
    index meta_key, value;
}

entity account_auth_descriptor {
    id: byte_array;
    key account, id;
    index id;
    auth_type;
    args: byte_array;
    rules: byte_array;
    mutable ctr: integer;
}

entity auth_descriptor_participant {
    key account_auth_descriptor, id: byte_array;
}

// rate limiter
entity rl_state {
    key account;
    mutable points: integer;
    mutable last_update: timestamp;
    mutable max_points: integer;
    mutable recovery_time: timestamp;
}


function add_auth_descriptor_to_account(account, auth_descriptor): byte_array {
    val id = auth_descriptor.hash();

    val account_auth_descriptor = create account_auth_descriptor (
        account, id,
        auth_descriptor.auth_type,
        args = auth_descriptor.args.to_gtv().to_bytes(),
        rules = auth_descriptor.rules.to_gtv().to_bytes(),
        0
    );

    when (auth_descriptor.auth_type) {
        S, M -> _add_ft_auth_participant(account, auth_descriptor, account_auth_descriptor);
        ES, EM -> _add_eth_auth_participant(account, auth_descriptor, account_auth_descriptor);
    }

     setup_auth_descriptor_variables(account_auth_descriptor);
     return id;
}

function _delete_auth_descriptor(auth_descriptor: account_auth_descriptor) {
    require(auth_descriptor.account.id != auth_descriptor.id, "Can't delete initial auth descriptor");
    delete auth_descriptor_rule_variable @* { auth_descriptor };
    delete auth_descriptor_participant @* { auth_descriptor };
    delete auth_descriptor;
}

function _delete_all_auth_descriptors_exclude(auth_descriptor: account_auth_descriptor) {
    delete (adrv: auth_descriptor_rule_variable, ad: account_auth_descriptor) @* {
        ad.account == auth_descriptor.account,
        ad.id != auth_descriptor.account.id,
        ad.id != auth_descriptor.id,
        adrv.account_auth_descriptor == ad    
    };
    delete (adp: auth_descriptor_participant, ad: account_auth_descriptor) @* {
        ad.account == auth_descriptor.account,
        ad.id != auth_descriptor.account.id,
        ad.id != auth_descriptor.id,
        adp.account_auth_descriptor == ad
    };
    delete account_auth_descriptor @* {
       .account == auth_descriptor.account,
       .id != auth_descriptor.account.id,
       .id != auth_descriptor.id
    };
}

function create_account_with_auth(auth_descriptor): byte_array {
    require(auth_descriptor.rules == null.to_gtv(), "Cannot create an account with a restricted auth descriptor");

    val id = auth_descriptor.hash();
    val acc = create account (id);

    add_auth_descriptor_to_account(acc, auth_descriptor);

    val max_points = config.rate_limit_max_points;
    val recovery_time = config.rate_limit_recovery_time;
    val points_at_start = config.rate_limit_points_at_account_creation;

    create rl_state(acc, .points = points_at_start, .last_update = op_context.last_block_time, max_points, recovery_time);

    return id;
}

function _add_ft_auth_participant(account, auth_descriptor, account_auth_descriptor) {
    val participants = get_participants(auth_descriptor.auth_type, auth_descriptor.args.to_gtv().to_bytes());
    require(op_context.get_signers().size() >= participants.size(), "Too few transaction signers");
    for (participant in participants) {
        require(op_context.is_signer(participant), "One participant in the Auth Desc didn't sign this transaction.");
        create auth_descriptor_participant(account_auth_descriptor, id = participant);
    }
}

function _add_eth_auth_participant(account, auth_descriptor, account_auth_descriptor) {
    for (participant in get_participants(auth_descriptor.auth_type, auth_descriptor.args.to_gtv().to_bytes())) {
        create auth_descriptor_participant(account_auth_descriptor, id = participant);
    }
}

function _auth(account: account, auth_descriptor: account_auth_descriptor, required_flags: list<text>) {
    rate_limit(account);
    require_auth(account, auth_descriptor, required_flags);
}

function auth_descriptor_by_id(account, id: byte_array) = require(
    account_auth_descriptor @? { account, id },
    "Auth descriptor '%s' not found for account '%s'".format(id, account.id)
);

function account_by_id(id: byte_array) = require(
    account @? { id },
    "Account not found: '%s'".format(id)
);

function single_sig_auth_descriptor(pubkey, flags: set<text>) = auth_descriptor(
    auth_type = auth_type.S,
    args = [
        flags.to_gtv(),
        pubkey.to_gtv()
    ],
    null.to_gtv()
);

function get_paginated_auth_descriptors(id: byte_array, page_size: integer, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return account_auth_descriptor @* {
        .account.id == id,
        .rowid > (before_rowid ?: rowid(0))
    } (
        @sort .rowid,
        auth_type = .auth_type,
        args = gtv.from_bytes(.args),
        rules = gtv.from_bytes(.rules)
    ) limit utils.fetch_data_size(page_size);
}

function get_paginated_accounts_by_ad_id(id: byte_array, page_size: integer, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return account_auth_descriptor @* {
        .id == id,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data=.account.id.to_gtv_pretty(),
            rowid=.rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

namespace Unsafe {
    //WARNING: doesn't check that the account is being created by the owner(s)
    function create_account_with_auth(auth_descriptor): byte_array {
        require(auth_descriptor.rules == null.to_gtv(), "Cannot create an account with a restricted auth descriptor");
        val id = auth_descriptor.hash();
        val acc = create account (id);
        _add_auth_descriptor(
            acc, auth_descriptor
        );
        val max_points = config.rate_limit_max_points;
        val recovery_time = config.rate_limit_recovery_time;
        val points_at_start = config.rate_limit_points_at_account_creation;

        create rl_state(acc, .points = points_at_start, .last_update = op_context.last_block_time, max_points, recovery_time);

        return id;
    }

    //WARNING: doesn't check that the auth_descriptor is being added by the participant(s) nor owner(s)
    function _add_auth_descriptor(account, auth_descriptor): byte_array {
        val id = auth_descriptor.hash();

        analyze_auth_descriptor_rules(auth_descriptor.rules, 0);

        when (auth_descriptor.auth_type) {
            S, ES -> single_sig_args.from_gtv(auth_descriptor.args.to_gtv());
            M, EM -> multi_sig_args.from_gtv(auth_descriptor.args.to_gtv());
        }

        val account_auth_descriptor = create account_auth_descriptor (
            account, id,
            auth_descriptor.auth_type,
            args = auth_descriptor.args.to_gtv().to_bytes(),
            rules = auth_descriptor.rules.to_gtv().to_bytes(),
            0
        );

        for (participant in get_participants(auth_descriptor.auth_type, auth_descriptor.args.to_gtv().to_bytes())) {
            create auth_descriptor_participant(account_auth_descriptor, id = participant);
        }

        setup_auth_descriptor_variables(account_auth_descriptor);
        return id;
    }
}

function rate_limit(account) {
    if (config.rate_limit_active == false) return;

    val max_counter = config.rate_limit_max_points;
    val recovery_time = config.rate_limit_recovery_time;
    val stat = require(
        rl_state@?{account} (.points, .last_update), 
        "Rate limiter state not found for the account with ID: %s".format(account.id)
    );
    val delta = op_context.last_block_time - stat.last_update;
    var got_points = 0;
    var update_time = stat.last_update;

    if (delta > recovery_time) {
        got_points = delta / recovery_time;
        update_time = stat.last_update + got_points * recovery_time;
        if (got_points + stat.points > max_counter) {
            got_points = max_counter - stat.points;
            // if user is at maximum reset his 
            // timer
            update_time = op_context.last_block_time;
        }
    }

    require(stat.points + got_points > 0, "Insufficient rate limiter points");

    update rl_state @ { account } (
        .points += got_points - 1,
        .last_update = update_time
    );
}

function add_rate_limit_points(account, amount: integer) {
    var state = require(
        rl_state@?{account}, 
        "Rate limiter state not found for the account with ID: %s".format(account.id)
    );
	state.points += amount;
}

object config {
    mutable rate_limit_active: boolean = chain_context.args.rate_limit_active;
    mutable rate_limit_max_points: integer = chain_context.args.rate_limit_max_points;
    mutable rate_limit_recovery_time: integer = chain_context.args.rate_limit_recovery_time;
    mutable rate_limit_points_at_account_creation: integer = chain_context.args.rate_limit_points_at_account_creation;
}

@mount("ft4.admin")
module;

import ^.accounts;
import ^.assets;
import ^.utils;

struct module_args {
    admin_pubkey: pubkey;
}

function require_admin() {
    require(
        op_context.is_signer(chain_context.args.admin_pubkey),
        "Expected admin signature"
    );
}

operation register_account(accounts.auth_descriptor) {
    require_admin();
    accounts.Unsafe.create_account_with_auth(auth_descriptor);
}

operation register_asset(name, symbol: text, decimals: integer, icon_url: text) {
    require_admin();
    assets.Unsafe.register_asset(name, symbol, decimals, chain_context.blockchain_rid, icon_url);
}

operation mint(account_id: byte_array, asset_id: byte_array, amount: big_integer) {
    require_admin();
    assets.Unsafe.mint(accounts.Account(account_id), assets.Asset(asset_id), amount);
}

operation add_rate_limit_points(account_id: byte_array, amount: integer) {
    require_admin();
	accounts.add_rate_limit_points(accounts.Account(account_id), amount);
}

import acc: ^.accounts;

entity asset {
    key id: byte_array;
    name;
    key symbol: text;
    decimals: integer;
    issuing_brid: byte_array;
    icon_url: text;
    mutable total_supply: big_integer;
}

function Asset(id: byte_array) = require(
    asset @? { id },
    "Asset <%s> not found".format(id)
);

entity balance {
    key acc.account, asset;
    mutable amount: big_integer = 0L;
}

val max_asset_amount = big_integer.from_hex("ff".repeat(32));

function ensure_balance(acc.account, asset): balance {
    val balance = balance @? {asset, account};
    if (balance != null) {
       return balance;
    }
    else return create balance(account, asset, amount = 0L);
}

function get_paginated_asset_balances(account_id: byte_array, page_size: integer, page_cursor: text?): list<utils.pagination_result> {
    val before_rowid = utils.before_rowid(page_cursor);
    return balance @* {
        .account.id == account_id,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (
                asset = (
                    id = .asset.id,
                    name = .asset.name,
                    symbol = .asset.symbol,
                    decimals = .asset.decimals,
                    brid = .asset.issuing_brid,
                    supply = .asset.total_supply,
                    icon_url = .asset.icon_url
                ),
                amount = .amount
            ).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function get_all_assets_paginated(page_size: integer, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return assets.asset @* {
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (
                id = .id,
                symbol = .symbol,
                name = .name,
                decimals = .decimals,
                brid = .issuing_brid,
                icon_url = .icon_url,
                supply = .total_supply
            ).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function get_asset_balances(account_id: byte_array) {
    return balance @* { .account.id == account_id } (
        asset = (
            id = .asset.id,
            name = .asset.name,
            decimals = .asset.decimals,
            brid = .asset.issuing_brid,
            supply = .asset.total_supply
        ),
        amount = .amount
    );
}

function format_amount_with_decimals(amount: big_integer, decimals: integer): text {
    require(decimals >= 0, "Decimals must be non-negative. Received: %s".format(decimals));
    var amt = amount.to_text();
    if (decimals == 0) {
        return amt;
    } else if (amt.size() > decimals) {
        amt = amt.sub(0, amt.size() - decimals) + "." + amt.sub(amt.size() - decimals);
    } else {
        amt = "0." + "0".repeat(decimals - amt.size()) + amt;
    }
    return amt;
}

function get_paginated_asset_balances_by_name(name, page_size: integer, page_cursor: text?) {
    val before_rowid = utils.before_rowid(page_cursor);
    return assets.asset @* {
        .name == name,
        .rowid > (before_rowid ?: rowid(0))
    } (
        utils.pagination_result(
            data = (
                id = .id,
                name = .name,
                symbol = .symbol,
                decimals = .decimals,
                brid = .issuing_brid,
                icon_url = .icon_url,
                supply = .total_supply
            ).to_gtv_pretty(),
            rowid = .rowid
        )
    ) limit utils.fetch_data_size(page_size);
}

function require_zero_exclusive_asset_amount_limits(value: big_integer, name) {
    require(
        value <= max_asset_amount, 
        "%s: value must be lower than 2^256, actual: %d".format(name, value)
    );
    require(
        value > 0L, 
         "%s: value must be non-zero positive, actual: %d".format(name, value)
    );
}

namespace Unsafe {
    function mint(acc.account, asset, amount: big_integer) {
        require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
        require(
            asset.issuing_brid == chain_context.blockchain_rid,
            "Assets can only be minted on issuing chain"
        );
        before_mint(account, asset, amount);
        val balance = ensure_balance(account, asset);

        balance.amount += amount;
        asset.total_supply += amount;

        require(asset.total_supply <= max_asset_amount, "End total supply must be lower than 2^256");

        create payment_history_entry(
            account,
            asset,
            .delta = amount,
            .op_index = op_context.op_index,
            .is_input = false,
            .entry_index = 0,
            transfer_args = [
                [(
                    amount, 
                    account_id = null.to_gtv().to_bytes(), 
                    entry_index = 0
                )],
                [(
                    amount, 
                    account_id = account.id,
                    entry_index = 0
                )]
            ].to_gtv().to_bytes()
        );

        after_mint(account, asset, amount);
    }

    function burn(acc.account, asset, amount: big_integer) {
        require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
        require(
            asset.issuing_brid == chain_context.blockchain_rid,
            "Assets can only be burned on issuing chain"
        );
        val balance = balance @ {asset, account};
        require(balance.amount >= amount, "Insufficient balance");

        before_burn(account, asset, amount);

        balance.amount -= amount;
        asset.total_supply -= amount;

        create payment_history_entry (
            account,
            asset,
            .delta = amount,
            .op_index = op_context.op_index,
            .is_input = true,
            .entry_index = 0,
            transfer_args = [
                [(
                    amount, 
                    account_id = account.id,
                    entry_index = 0
                )],
                [(
                    amount, 
                    account_id = null.to_gtv().to_bytes(), 
                    entry_index = 0
                )]
            ].to_gtv().to_bytes()
        );
        after_burn(account, asset, amount);
    }

    function register_asset(
        name,
        symbol: text,
        decimals: integer,
        blockchain_rid: byte_array,
        icon_url: text): asset {
        require(decimals >= 0 and decimals < 79, "Decimals must be between 0 and 78 (included)");

        val trimmed_icon_url = icon_url.trim();
        require(
            (trimmed_icon_url == "") or (trimmed_icon_url.size() <= 2048 and trimmed_icon_url.matches('^\\S+:\\/\\/[^\\s$.?#].[^\\s]*$')),
            "Invalid URL for icon"
        );

        val id = (name, blockchain_rid).hash();
        return create asset (
            id,
            name,
            symbol,
            decimals,
            issuing_brid=blockchain_rid,
            icon_url=trimmed_icon_url,
            total_supply=0L
        );
    }
}

@extendable function before_transfer_one(from: acc.account, to: acc.account, assets.asset, amount: big_integer);

@extendable function after_transfer_one(from: acc.account, to: acc.account, assets.asset, amount: big_integer);

@extendable function before_transfer(inputs: list<xfer_input>, outputs: list<xfer_output>);

@extendable function after_transfer(inputs: list<xfer_input>, outputs: list<xfer_output>);

@extendable function before_mint(acc.account, asset, amount: big_integer);

@extendable function after_mint(acc.account, asset, amount: big_integer);

@extendable function before_burn(acc.account, asset, amount: big_integer);

@extendable function after_burn(acc.account, asset, amount: big_integer);

import ^^.assets;
import ^^.auth;

query transfer_auth_data(gtv) = auth.auth_data(["T"], "Do you want to transfer %s from account %s to account %s? Nonce: %s");

// TODO: remove
@extend(auth.auth_handler)
function () = auth.add_auth_handler(
    scope = "ft4.transfer",
    flags = ["T"]
);

operation transfer(inputs: list<assets.xfer_input>, outputs: list<assets.xfer_output>) {
    assets._transfer(inputs, outputs);
}

function transfer_message(gtv) {
    val params = struct<transfer_one>.from_gtv(gtv);
    val asset = assets.Asset(params.asset_id);

    return "Please sign the message\nto transfer %s %s\n\nfrom:\n{account_id}\n\nto:\n%s\n\nNonce: {nonce}"
        .format(
            assets.format_amount_with_decimals(params.amount, asset.decimals),
            asset.name,
            params.receiver_id
        );
}

@extend(auth.auth_handler)
function () = auth.add_auth_handler(
    scope = "ft4.transfer_one",
    flags = ["T"],
    message = transfer_message(*)
);

operation transfer_one(receiver_id: byte_array, asset_id: byte_array, amount: big_integer) {
    val account = auth.authenticate();
    assets.Unsafe.transfer_one(account, acc.Account(receiver_id), assets.Asset(asset_id), amount);
}

@extend(auth.auth_handler)
function () = auth.add_auth_handler(
    scope = "ft4.burn",
    flags = ["T"],
    message = burn_message(*)
);

function burn_message(gtv) {
    val params = struct<burn>.from_gtv(gtv);
    val asset = assets.Asset(params.asset_id);

    return "Please sign the message\nto burn %s %s\n\nfrom:\n{account_id}\n\nNonce: {nonce}"
        .format(
            assets.format_amount_with_decimals(params.amount, asset.decimals),
            asset.name
        );
}

operation burn(asset_id: byte_array, amount: big_integer) {
    val account = auth.authenticate();
    assets.Unsafe.burn(account, assets.Asset(asset_id), amount);
}

import ^^.assets;
import acc: ^^.accounts;
import ^^.utils;

query get_asset_balances(account_id: byte_array) {
    return assets.get_asset_balances(account_id);
}

query get_asset_balances_paginated(account_id: byte_array, page_size: integer, page_cursor: text?) {
    return utils.make_page(
        assets.get_paginated_asset_balances(account_id, page_size, page_cursor),
        page_size
    );
}

query get_asset_balance(account_id: byte_array, asset_id: byte_array) {
    return assets.balance @? {
        .account.id == account_id,
        .asset.id == asset_id
    } (
        asset = extract_asset_data(.asset),
        amount = .amount
    );
}

query get_asset_by_name(name) {
    return assets.asset @* { name } ( extract_asset_data($) );
}

query get_assets_by_name_paginated(name, page_size: integer, page_cursor: text?) {
    return utils.make_page(
        assets.get_paginated_asset_balances_by_name(name, page_size, page_cursor),
        page_size
    );
}

query get_asset_by_id(asset_id: byte_array) {
    return assets.asset @? { .id == asset_id } ( extract_asset_data($) );
}

query get_asset_by_symbol(symbol: text) {
    return assets.asset @? { .symbol == symbol } ( extract_asset_data($) );
} 

query get_all_assets() {
    return assets.asset @* {} ( extract_asset_data($) );
}

query get_all_assets_paginated(page_size: integer, page_cursor: text?) {
    return utils.make_page(
        assets.get_all_assets_paginated(page_size, page_cursor),
        page_size
    );
}

query get_transfer_history(account_id: byte_array, filter: assets.filter, page_size: integer, page_cursor: text?) {
    val account = acc.account @? { account_id };
    if (empty(account)) return null;

    val paginated_payments = assets.get_paginated_payments(account, filter, page_size, page_cursor);
    return utils.make_page(paginated_payments, page_size);
}

query get_transfer_history_entry(rowid) {
    val entry = assets.payment_history_entry @? { .rowid == rowid };
    return if (empty(entry)) null else assets.extract_data_from_payment_history_entry(entry);
}

function extract_asset_data(assets.asset) {
    return (
        id = asset.id,
        symbol = asset.symbol,
        name = asset.name,
        decimals = asset.decimals,
        brid = asset.issuing_brid,
        icon_url = asset.icon_url,
        supply = asset.total_supply
    );
}

import acc: ^.accounts;
import ^.assets;
import ^.utils;

@log entity payment_history_entry {
    index acc.account, asset;
    delta: big_integer;

    // helps to locate exact position of payment entry in transaction
    op_index: integer;
    is_input: boolean;
    entry_index: integer;
    transfer_args: byte_array;
}

enum transfer_type {
    sent,
    received,
}

struct filter {
    transfer_type?;
}

function extract_data_from_payment_history_list(
        entries: list<payment_history_entry>
    ): list<(data:gtv,rowid:rowid)> {
    return entries @* {} (
        data = extract_data_from_payment_history_entry($).to_gtv_pretty(),
        rowid = .rowid
    );
}

function extract_operation_name(entry: payment_history_entry): text {
    val gtx = gtx_transaction.from_gtv(gtv.from_bytes(entry.transaction.tx_data));
    return gtx.body.operations[entry.op_index].name;
}

function extract_data_from_payment_history_entry(entry: payment_history_entry) {
    return (
        id = '%d'.format(entry.rowid),
        delta = entry.delta,
        decimals = entry.asset.decimals,
        asset = entry.asset.name,
        asset_id = entry.asset.id,
        is_input = entry.is_input,
        timestamp = entry.transaction.block.timestamp,
        block_height = entry.transaction.block.block_height,
        entry_index = entry.entry_index,
        transfer_args = entry.transfer_args,
        tx_rid = entry.transaction.tx_rid,
        tx_data = entry.transaction.tx_data,
        operation_name = extract_operation_name(entry)
    );
}

function get_paginated_payments(acc.account, filter, page_size: integer, page_cursor: text?) {
    var before_rowid: rowid? = null;
    if (page_cursor??) {
        val cursor = utils.decode_cursor(page_cursor);
        before_rowid = cursor.before_rowid;
    }

    val entries = payment_history_entry @* {
        account,
        if (filter.transfer_type == null) true else .is_input == (filter.transfer_type!! == transfer_type.sent), 
        if (before_rowid??) (.rowid < before_rowid) else true
    } (@sort_desc $) limit utils.fetch_data_size(page_size);

    return extract_data_from_payment_history_list(entries) @* {} (
        utils.pagination_result(
            data = .data,
            rowid = .rowid
        )
    );
}

import acc: ^.accounts;

struct xfer_input {
   account_id: byte_array;
   asset_id: byte_array;
   auth_descriptor_id: byte_array;
   amount: big_integer;
   extra: map<text, gtv>;
}

struct xfer_output {
   account_id: byte_array;
   asset_id: byte_array;
   amount: big_integer;
   extra: map<text, gtv>;
}

function deduct_balance(acc.account, asset, amount: big_integer) {
    val balance = balance @ { account, asset };
    require(balance.amount >= amount, "Balance is too low");
    balance.amount -= amount;
}

function consume_input (
   i: xfer_input, 
   idx: integer, 
   assets: map<asset, big_integer>,
   entries: map<
      asset, 
      (
         list<(
            amount: big_integer, 
            account: acc.account, 
            entry_index: integer
         )>, 
         list<(
            amount: big_integer, 
            account: acc.account, 
            entry_index: integer
         )>
      )
   >
) {
      val asset = asset @ { .id == i.asset_id };

      if (asset not in entries) {
         entries[asset] = (
            list<(
               amount: big_integer, 
               account: acc.account, 
               entry_index: integer
            )>(), 
            list<(
               amount: big_integer, 
               account: acc.account, 
               entry_index: integer
            )>()
         );
      }

      val account = acc.account @ { .id == i.account_id };
      acc._auth(
         account, 
         acc.account_auth_descriptor @ { 
            .id == i.auth_descriptor_id, 
            .account == account
         },
         ["T"]
      );
      require( i.amount > 0, "Tx inputs must be non 0 positive." );

      deduct_balance(account, asset, i.amount);
      assets[asset] = i.amount + if (asset in assets) assets[asset] else 0L;
      entries[asset][0].add(
         (amount = i.amount, account = account, entry_index = idx)
      );
}

function process_transfer_output (
   o: xfer_output, 
   idx: integer, 
   available_assets: map<asset, big_integer>,
   entries: map<
      asset, 
      (
         list<(
            amount: big_integer, 
            account: acc.account, 
            entry_index: integer
         )>, 
         list<(
            amount: big_integer, 
            account: acc.account, 
            entry_index: integer
         )>
      )
   >
) {
      if (o.extra.contains("reg_auth_desc")) {
          val auth_desc = acc.auth_descriptor.from_gtv(o.extra["reg_auth_desc"]);
          require(
            o.account_id == acc.create_account_with_auth(auth_desc),
            "Account id in output does not match auth descriptor id to be registered"
         );
      }

      val target_account = acc.account @ { .id == o.account_id };
      val asset = asset @ { .id == o.asset_id };
      require(o.amount > 0, "Tx outputs must be non-zero positive");
      require(
         available_assets[asset] >= o.amount, 
         "Transfer output sum exceeds input sum"
      );
      available_assets[asset] -= o.amount;
      val balance = ensure_balance(target_account, asset);
      balance.amount += o.amount;

      entries[asset][1].add(
         (amount = o.amount, account = target_account, entry_index = idx)
      );
}

function _transfer(inputs: list<xfer_input>, outputs: list<xfer_output>) {
   before_transfer(inputs, outputs);

   val entries = map<
      asset, 
      (
         list<(
            amount: big_integer, 
            account: acc.account, 
            entry_index: integer
         )>, 
         list<(
            amount: big_integer, 
            account: acc.account, 
            entry_index: integer
         )>
      )
   > ();

   val sum_inputs = map<asset, big_integer>();
   var idx = 0;
   for (i in inputs) {
      consume_input(i, idx, sum_inputs, entries);
      idx += 1;
   }

   idx = 0;
   for (o in outputs) {
      process_transfer_output(o, idx, sum_inputs, entries);
      idx += 1;
   }

   for ((asset, v) in entries) {
      val ins = entries[asset][0] @* {} (.amount, .account.id, .entry_index);
      val outs = entries[asset][1] @* {} (.amount, .account.id, .entry_index);
      val args = [ins, outs];

      for (entry in v[0]) {
         create payment_history_entry(
            .account = entry.account,
            .asset = asset,
            .delta = entry.amount,
            .op_index = op_context.op_index,
            .is_input = true,
            .entry_index = entry.entry_index,
            .transfer_args = args.to_gtv().to_bytes()
         );
      }
      for (entry in v[1]) {
         create payment_history_entry(
            .account = entry.account,
            .asset = asset,
            .delta = entry.amount,
            .op_index = op_context.op_index,
            .is_input = false,
            .entry_index = entry.entry_index,
            .transfer_args = args.to_gtv().to_bytes()
         );
      }
   }

   after_transfer(inputs, outputs);
}

namespace Unsafe {

   function transfer_one(from: acc.account, to: acc.account, assets.asset, amount: big_integer) {
      require_zero_exclusive_asset_amount_limits(amount, "Parameter amount");
      require(from != to, "Sender and receiver have to be different");

      val args = [
         [(amount, from.id, 0)],
         [(amount, to.id, 0)]
      ];

      before_transfer_one(from, to, asset, amount);

      deduct_balance(from, asset, amount);
      create payment_history_entry(
         .account = from,
         .asset = asset,
         .delta = amount,
         .op_index = op_context.op_index,
         .is_input = true,
         .entry_index = 0,
         .transfer_args = args.to_gtv().to_bytes()
      );

      ensure_balance(to, asset).amount += amount;
      create payment_history_entry(
         .account = to,
         .asset = asset,
         .delta = amount,
         .op_index = op_context.op_index,
         .is_input = false,
         .entry_index = 0,
         .transfer_args = args.to_gtv().to_bytes()
      );

      after_transfer_one(from, to, asset, amount);
   }
}

function authenticate() {
    val op = op_context.get_all_operations()[op_context.op_index];
    val flags = get_auth_flags(op.name);
    // FIXME: call from evm auth handler instead from this place
    val message = get_auth_message_template(op.name, op.args.to_gtv());
    return accounts._authenticate(set(flags), message);
}

val DEFAULT_LOGIN_CONFIG_NAME = "default";

query get_login_config(name? = null) {
    val configs = login_config();
    val config_name = name ?: DEFAULT_LOGIN_CONFIG_NAME;

    if (config_name == DEFAULT_LOGIN_CONFIG_NAME) {
        return if (config_name in configs) configs[config_name] else _login_config(flags = []);
    }

    return require(
        configs.get_or_null(config_name), 
        "Unknown login configuration <%s>".format(config_name)
    );
}

struct _login_config {
    flags: list<text>;
}

@extendable
function login_config(): map<name, _login_config>;

function add_login_config(name = DEFAULT_LOGIN_CONFIG_NAME, flags: list<text>) {
    return [name: _login_config(flags)];
}

@mount('ft4')
module;

import ^.accounts;

struct auth_data {
    flags: list<text>;
    message: text;
}

struct _auth_handler {
    flags: list<text>;
    message_formatter: ((gtv) -> text)? = null;
}

/*
 * The constant that defines app level authentication scope.
 * If scope is omitted when defining an auth handler, then
 * it has 'app' scope, i.e. it is used to authenticate 
 * operations that do not have own auth handlers or if 
 * there is no mount point auth handler for the operation.
 */
val APP_SCOPE = "app";

/*
 * Extendable function used to define auth handlers. 
 * When called it returns a list of all auth handlers defined
 * in the dapp.
 */
@extendable 
function auth_handler(): map<name, _auth_handler>;

/*
 * Finds auth handler for provided operation name.
 */
function get_auth_handler(op_name: name) {
    require_valid_scope_name(op_name);
    val auth_handlers = auth_handler();
    if (op_name in auth_handlers) return auth_handlers[op_name];

    val handler = get_mount_scope_auth_handler(auth_handlers, op_name);
    if (handler??) return handler;

    return require(
        auth_handlers.get_or_null(APP_SCOPE), 
        "Cannot find auth handler for operation <%s>".format(op_name)
    );
}

function add_auth_handler(scope: text = APP_SCOPE, flags: list<text>, message: ((gtv) -> text)? = null) {
    val scope_name = scope.trim();
    require_valid_scope_name(scope_name);
    return [scope_name: _auth_handler(flags, message)];
}

function args() = op_context.get_all_operations()[op_context.op_index].args.to_gtv();

struct signature {
    r: byte_array;
    s: byte_array;
    v: integer;
}

function get_mount_scope_auth_handler(auth_handlers: map<name, _auth_handler>, op_name: name) {
    val op_name_components = op_name.split(".");
    if (op_name_components.size() < 2) return null;

    for (count in range(op_name_components.size()-1, 0, -1)) {
        val mount_point = join_text_list(op_name_components, count);
        if (mount_point in auth_handlers) return auth_handlers[mount_point];
    }

    return null;
}

/*
 * Creates message from operation name and arguments.
 * It is used when `evm_auth` is used to authenticate a user, 
 * but auth message is not specified in the auth handler of the operation.
 */
function generate_auth_message_template(brid: byte_array, op: gtx_operation) {
    var message = "Please sign the message to call\noperation:\n- %s\n\n".format(op.name);

    if (op.args.size() > 0) {
        var arguments = "with arguments:\n";
        for (arg in op.args) {
            arguments = arguments + "- %s\n".format(arg).replace("\"", "");
        }
        message = message + arguments + "\n";
    }

    return message + "Nonce: {nonce}";
}

function join_text_list(components: list<text>, count: integer) {
    require(count < components.size() and count > 0, "Error building mount path");
    var result = components[0];
    for (i in range(1, count)) {
        result = result + "." + components[i];
    }
    return result;
}

function require_valid_scope_name(name) =     
    require(
        name.matches("^\\w+(\\.\\w+)*$"), 
        "Invalid scope name <%s>".format(name)
    );

operation evm_auth(
    account_id: byte_array,
    auth_descriptor_id: byte_array,
    signatures: list<signature>
) {}

operation ft_auth(
    account_id: byte_array,
    auth_descriptor_id: byte_array
) {}

query get_auth_flags(op_name: name) = get_auth_handler(op_name).flags;

query get_auth_message_template(op_name: name, op_args: gtv) {
    val formatter = get_auth_handler(op_name).message_formatter;

    return if (formatter??) formatter(op_args) else generate_auth_message_template(chain_context.blockchain_rid, gtx_operation(
        name = op_name,
        args = list<gtv>.from_gtv(op_args)
    ));
}

