@mount('ft4')
module;

import ^^.admin;
import acc: ^^.accounts; 

/*
 * We can store the error message in this singleton, and later check it in our tests.
 */
object dev_error {
    mutable msg: text = "valid";
}

/*
 * This operation does NOTHING but authenticates the transaction. 
 * Only used for testing of authentication mechanics.
 */
operation dev_auth(account_id: byte_array, auth_descriptor_id: byte_array, required_flags: list<text>) {
    val account = acc.account @ { .id == account_id };

    val acc_auth_desc = acc.account_auth_descriptor @ {
          .id == auth_descriptor_id,
          .account == account
    };
    val participants = acc.get_participants(acc_auth_desc.auth_type, acc_auth_desc.args);

    val result = acc.check_auth_args(
       		acc_auth_desc.auth_type,
       		acc_auth_desc.args,
            participants,
       		required_flags
	);

    if (result.valid) {
        dev_error.msg = "valid";
    } else {
        dev_error.msg = result.error!!;
    }
}

operation dev_authenticated_operation(message_template: text) {
  admin.require_admin();
  acc._authenticate(set<text>(["A"]), message_template);
}

operation add_auth_descriptor_for_account(account: acc.account, desc: acc.auth_descriptor) {
  admin.require_admin();
  acc.add_auth_descriptor_to_account(account, desc);
}

operation dev_perform_large_transfer(
  amount: integer,
  to: text
) {
  val msg_template = "Do you want to send {0} CHR to {1}? Nonce: {nonce}";
  acc._authenticate(set(["A"]), msg_template);
}

struct page_cursor {
    before_rowid: rowid? = null;
}

struct pagination_result {
    data: gtv;
    rowid: rowid;
}

val MAX_PAGE_SIZE: integer = 100;

function encode_cursor(page_cursor) = page_cursor.to_bytes().to_base64();

function decode_cursor(cursor: text) = page_cursor.from_bytes(byte_array.from_base64(cursor));

struct paged_result {
    next_cursor: text?;
    data: list<gtv>;
}

function null_page() = paged_result(
    next_cursor = null,
    data = list<gtv>()
);

function fetch_data_size(page_size: integer) = min(MAX_PAGE_SIZE, page_size) + 1;

function before_rowid(page_cursor: text?) {
    var before_rowid: rowid? = null;
    if (page_cursor??) {
        val cursor = decode_cursor(page_cursor);
        before_rowid = cursor.before_rowid;
    }
    return before_rowid;
}


function make_page(pagination_results: list<pagination_result>, page_size: integer): paged_result {
    require(page_size > 0, "Must return at least one item");
    if (empty(pagination_results)) {
         return null_page();
    }
    // adding +1 should help with next page null situation when current page size
    // is equal to max page size
    if(pagination_results.size() < fetch_data_size(page_size)) {
        return paged_result(
            next_cursor = null,
            data = pagination_results  @* {} .data
        );
    }
    val paginated_result = pagination_results.sub(0, pagination_results.size()-1);
    val next_id = pagination_results[pagination_results.size()-2].rowid;
    val next_cursor = page_cursor(
        next_id
    );
    return paged_result(
        next_cursor = encode_cursor(next_cursor),
        data = paginated_result  @* {} .data
    );
}

/*
 * For complex validation we might not want to use simple "require()"
 * but an error message that is returned. 
 */
struct validation_result {
    valid: boolean;
    error: text? = null;
}

val VALID = validation_result(true, null);

function invalid(error: text) = validation_result(false, error);

